package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.world.level.ChunkPos;
/** Bounded personal excavation areas; unknown historical coordinates are never assigned to a player. */
public final class NativeOreAreas {
 public static final int LIMIT=8192,PER_SCOPE=512;
 private static final Set<String> METRICS=Set.of("coal","iron","copper");
 private record Area(UUID player,ProfessionRank band,long chunk){}
 private final Map<Area,Map<String,Integer>> areas=new HashMap<>();
 public boolean canRecord(UUID player,ProfessionRank band,long chunk){return areas.containsKey(new Area(player,band,chunk))||areas.size()<LIMIT&&areas.keySet().stream().filter(a->a.player().equals(player)&&a.band()==band).count()<PER_SCOPE;}
 public void record(UUID player,ProfessionRank band,long chunk,String metric){if(!METRICS.contains(metric)||!canRecord(player,band,chunk))throw new IllegalArgumentException("Native excavation area unavailable");var values=areas.computeIfAbsent(new Area(player,band,chunk),a->new HashMap<>());values.merge(metric,1,Math::addExact);}
 public int copper(UUID player,ProfessionRank band,int separation){if(separation<1||separation>8)throw new IllegalArgumentException("Area separation outside1..8chunks");var scope=areas.entrySet().stream().filter(e->e.getKey().player().equals(player)&&e.getKey().band()==band).toList();var bases=scope.stream().filter(e->e.getValue().getOrDefault("coal",0)>0||e.getValue().getOrDefault("iron",0)>0).map(e->e.getKey().chunk()).toList();if(bases.isEmpty())return 0;int total=0;for(var area:scope){int copper=area.getValue().getOrDefault("copper",0);if(copper==0)continue;long chunk=area.getKey().chunk();boolean separate=bases.stream().noneMatch(base->Math.max(Math.abs((long)ChunkPos.getX(chunk)-ChunkPos.getX(base)),Math.abs((long)ChunkPos.getZ(chunk)-ChunkPos.getZ(base)))<separation);if(separate)total=Math.addExact(total,copper);}return total;}
 public List<String> history(UUID player,int limit){if(limit<1||limit>16)throw new IllegalArgumentException("Inspect at most16areas");return areas.entrySet().stream().filter(e->e.getKey().player().equals(player)).sorted(Comparator.comparing(e->e.getKey().band().id()+":"+e.getKey().chunk())).limit(limit).map(e->e.getKey().band().id()+" chunk="+ChunkPos.getX(e.getKey().chunk())+","+ChunkPos.getZ(e.getKey().chunk())+" "+new java.util.TreeMap<>(e.getValue())).toList();}
 public ListTag save(){var list=new ListTag();areas.entrySet().stream().sorted(Comparator.comparing(e->e.getKey().player()+":"+e.getKey().band().id()+":"+e.getKey().chunk())).forEach(e->{var row=new CompoundTag();row.putUUID("player",e.getKey().player());row.putString("band",e.getKey().band().id());row.putLong("chunk",e.getKey().chunk());var counts=new CompoundTag();e.getValue().forEach(counts::putInt);row.put("counts",counts);list.add(row);});return list;}
 public static NativeOreAreas load(ListTag rows,ProfessionEvidence proof){if(rows.size()>LIMIT||!rows.isEmpty()&&rows.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Invalid excavation areas");var result=new NativeOreAreas();record Key(UUID player,ProfessionRank band,String metric){}var sums=new HashMap<Key,Integer>();for(var value:rows){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("player","band","chunk","counts"))||!row.hasUUID("player")||!row.contains("band",Tag.TAG_STRING)||!row.contains("chunk",Tag.TAG_LONG)||!row.contains("counts",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Invalid excavation area");var band=Arrays.stream(ProfessionRank.values()).filter(b->b.id().equals(row.getString("band"))).findFirst().orElseThrow(()->new IllegalArgumentException("Unknown excavation band"));var area=new Area(row.getUUID("player"),band,row.getLong("chunk"));var counters=row.getCompound("counts");if(counters.isEmpty()||!METRICS.containsAll(counters.getAllKeys())||result.areas.containsKey(area)||!result.canRecord(area.player(),band,area.chunk()))throw new IllegalArgumentException("Duplicate or excessive excavation area");var values=new HashMap<String,Integer>();for(String metric:counters.getAllKeys()){if(!counters.contains(metric,Tag.TAG_INT)||counters.getInt(metric)<1||counters.getInt(metric)>NativeOreEvidence.LIMIT)throw new IllegalArgumentException("Invalid excavation count");int n=counters.getInt(metric);values.put(metric,n);var key=new Key(area.player(),band,metric);int sum=sums.merge(key,n,Math::addExact);if(sum>proof.count(area.player(),band,metric))throw new IllegalArgumentException("Area exceeds authenticated mining count");}result.areas.put(area,values);}return result;}
}
